document.addEventListener("DOMContentLoaded",(()=>{fetch("/api/standings-data/").then((e=>{if(!e.ok)throw new Error("Network response was not ok");return e.json()})).then((e=>{console.log(e);const t=e,n=document.getElementById("standings-container");let o=1;for(const e of t){const t=document.createElement("tr"),d=document.createElement("th");d.scope="row",d.textContent=o,o+=1,t.appendChild(d);for(const n of["Team","GP","W","L","GB","W %","PF","PA","PD(+/-)"]){const o=document.createElement("td");o.textContent=e[n],t.appendChild(o)}n.appendChild(t)}document.getElementById("loading-div").remove()})).catch((e=>{console.error("There was a problem with the fetch operation:",e)}))}));